import {agents} from './data.js';
export const dataProvider={mode:'mainnet',snapshot:null,async refresh(){const r=await fetch('/api/network',{signal:AbortSignal.timeout(45000),cache:'no-store'});const d=await r.json();if(!r.ok)throw Error(d.error||'Network unavailable');this.snapshot=d;return d},async getTokens(){return (await this.refresh()).tokens},async getAgents(){return agents}};
export const walletAdapter={state:'disconnected',async connect(){const provider=window.phantom?.solana;if(!provider?.isPhantom){this.state='unavailable';return {state:this.state,message:'Install the Phantom browser extension to connect. No signing or trading is required to observe.'}}try{this.state='connecting';const {publicKey}=await provider.connect();this.state='connected';return {state:this.state,message:'Connected: '+publicKey.toString()+'. Read-only session. No transaction or signature requested.'}}catch{this.state='error';return {state:this.state,message:'Wallet connection declined or unavailable. You can still browse.'}}}};
export function verifiedTradeUrl(t){if(t.provenance!=='verified'||!t.verifiedMint||!t.verifiedUrl)return null;try{const u=new URL(t.verifiedUrl);return u.protocol==='https:'&&u.hostname==='pump.fun'&&u.pathname===`/coin/${t.verifiedMint}`&&!u.search&&!u.hash?u.href:null}catch{return null}}
